import{_ as p,a0 as d,w as o,s as r,I as e,x as i,a1 as n,A as l,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 中找到並刪除重複文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中找到並刪除重複文件 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中找到並刪除重複文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中找到並刪除重複文件 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180927 How To Find And Delete Duplicate Files In Linux","title":"如何在 Linux 中找到並刪除重複文件","tag":"201810","desc":""},"relativePath":"201810/20180927 How To Find And Delete Duplicate Files In Linux.md","filePath":"[post].md"}'),h={name:"201810/20180927 How To Find And Delete Duplicate Files In Linux.md"};function g(u,s,k,c,b,f){const a=d("Link");return o(),r("div",null,[s[38]||(s[38]=e("h1",{id:"如何在-linux-中找到並刪除重複文件",tabindex:"-1"},[i("如何在 Linux 中找到並刪除重複文件 "),e("a",{class:"header-anchor",href:"#如何在-linux-中找到並刪除重複文件","aria-label":"Permalink to “如何在 Linux 中找到並刪除重複文件”"},"​")],-1)),s[39]||(s[39]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/09/Find-And-Delete-Duplicate-Files-720x340.png",alt:""})],-1)),s[40]||(s[40]=e("p",null,"在編輯或修改配置文件或舊文件前，我經常會把它們備份到硬盤的某個地方，因此我如果意外地改錯了這些文件，我可以從備份中恢復它們。但問題是如果我忘記清理備份文件，一段時間之後，我的磁盤會被這些大量重複文件填滿 —— 我覺得要麼是懶得清理這些舊文件，要麼是擔心可能會刪掉重要文件。如果你們像我一樣，在類 Unix 操作系統中，大量多版本的相同文件放在不同的備份目錄，你可以使用下面的工具找到並刪除重複文件。",-1)),s[41]||(s[41]=e("p",null,[e("strong",null,"提醒一句：")],-1)),e("p",null,[s[1]||(s[1]=i("在刪除重複文件的時請儘量小心。如果你不小心，也許會導致",-1)),n(a,{href:"https://www.ostechnix.com/prevent-files-folders-accidental-deletion-modification-linux/"},{default:l(()=>[...s[0]||(s[0]=[i("意外丟失數據",-1)])]),_:1}),s[2]||(s[2]=i("。我建議你在使用這些工具的時候要特別注意。",-1))]),s[42]||(s[42]=e("h3",{id:"在-linux-中找到並刪除重複文件",tabindex:"-1"},[i("在 Linux 中找到並刪除重複文件 "),e("a",{class:"header-anchor",href:"#在-linux-中找到並刪除重複文件","aria-label":"Permalink to “在 Linux 中找到並刪除重複文件”"},"​")],-1)),s[43]||(s[43]=e("p",null,"出於本指南的目的，我將討論下面的三個工具：",-1)),s[44]||(s[44]=e("ol",null,[e("li",null,"Rdfind"),e("li",null,"Fdupes"),e("li",null,"FSlint")],-1)),s[45]||(s[45]=e("p",null,"這三個工具是自由開源的，且運行在大多數類 Unix 系統中。",-1)),s[46]||(s[46]=e("h4",{id:"_1-rdfind",tabindex:"-1"},[i("1. Rdfind "),e("a",{class:"header-anchor",href:"#_1-rdfind","aria-label":"Permalink to “1. Rdfind”"},"​")],-1)),e("p",null,[s[4]||(s[4]=e("strong",null,"Rdfind",-1)),s[5]||(s[5]=i(" 意即 ",-1)),s[6]||(s[6]=e("strong",null,"r",-1)),s[7]||(s[7]=i("edundant ",-1)),s[8]||(s[8]=e("strong",null,"d",-1)),s[9]||(s[9]=i("ata ",-1)),s[10]||(s[10]=e("strong",null,"find",-1)),s[11]||(s[11]=i("（冗餘數據查找），是一個通過訪問目錄和子目錄來找出重複文件的自由開源的工具。它是基於文件內容而不是文件名來比較。Rdfind 使用",-1)),s[12]||(s[12]=e("strong",null,"排序",-1)),s[13]||(s[13]=i("算法來區分原始文件和重複文件。如果你有兩個或者更多的相同文件，Rdfind 會很智能的找到原始文件並認定剩下的文件為重複文件。一旦找到副本文件，它會向你報告。你可以決定是刪除還是使用",-1)),n(a,{href:"https://www.ostechnix.com/explaining-soft-link-and-hard-link-in-linux-with-examples/"},{default:l(()=>[...s[3]||(s[3]=[i("硬鏈接或者符號（軟）鏈接",-1)])]),_:1}),s[14]||(s[14]=i("代替它們。",-1))]),s[47]||(s[47]=e("p",null,[e("strong",null,"安裝 Rdfind")],-1)),e("p",null,[s[17]||(s[17]=i("Rdfind 存在於 ",-1)),n(a,{href:"https://aur.archlinux.org/packages/rdfind/"},{default:l(()=>[...s[15]||(s[15]=[i("AUR",-1)])]),_:1}),s[18]||(s[18]=i(" 中。因此，在基於 Arch 的系統中，你可以像下面一樣使用任一如 ",-1)),n(a,{href:"https://www.ostechnix.com/yay-found-yet-another-reliable-aur-helper/"},{default:l(()=>[...s[16]||(s[16]=[i("Yay",-1)])]),_:1}),s[19]||(s[19]=i(" AUR 程序助手安裝它。",-1))]),s[48]||(s[48]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yay -S rdfind</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install rdfind</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install rdfind</span></span></code></pre></div><p>在 RHEL、CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install rdfind</span></span></code></pre></div><p><strong>用法</strong></p><p>一旦安裝完成，僅帶上目錄路徑運行 Rdfind 命令就可以掃描重複文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind ~/Downloads</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/rdfind-1.png" alt=""></p><p>正如你看到上面的截屏，Rdfind 命令將掃描 <code>~/Downloads</code> 目錄，並將結果存儲到當前工作目錄下一個名為 <code>results.txt</code> 的文件中。你可以在 <code>results.txt</code> 文件中看到可能是重複文件的名字。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat results.txt</span></span>
<span class="line"><span># Automatically generated</span></span>
<span class="line"><span># duptype id depth size device inode priority name</span></span>
<span class="line"><span>DUPTYPE_FIRST_OCCURRENCE 1469 8 9 2050 15864884 1 /home/sk/Downloads/tor-browser_en-US/Browser/TorBrowser/Tor/PluggableTransports/fte/tests/dfas/test5.regex</span></span>
<span class="line"><span>DUPTYPE_WITHIN_SAME_TREE -1469 8 9 2050 15864886 1 /home/sk/Downloads/tor-browser_en-US/Browser/TorBrowser/Tor/PluggableTransports/fte/tests/dfas/test6.regex</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>DUPTYPE_FIRST_OCCURRENCE 13 0 403635 2050 15740257 1 /home/sk/Downloads/Hyperledger(1).pdf</span></span>
<span class="line"><span>DUPTYPE_WITHIN_SAME_TREE -13 0 403635 2050 15741071 1 /home/sk/Downloads/Hyperledger.pdf</span></span>
<span class="line"><span># end of file</span></span></code></pre></div><p>通過檢查 <code>results.txt</code> 文件，你可以很容易的找到那些重複文件。如果願意你可以手動的刪除它們。</p><p>此外，你可在不修改其他事情情況下使用 <code>-dryrun</code> 選項找出所有重複文件，並在終端上輸出彙總信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -dryrun true ~/Downloads</span></span></code></pre></div><p>一旦找到重複文件，你可以使用硬鏈接或符號鏈接代替他們。</p><p>使用硬鏈接代替所有重複文件，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -makehardlinks true ~/Downloads</span></span></code></pre></div><p>使用符號鏈接/軟鏈接代替所有重複文件，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -makesymlinks true ~/Downloads</span></span></code></pre></div><p>目錄中有一些空文件，也許你想忽略他們，你可以像下面一樣使用 <code>-ignoreempty</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -ignoreempty true ~/Downloads</span></span></code></pre></div><p>如果你不再想要這些舊文件，刪除重複文件，而不是使用硬鏈接或軟鏈接代替它們。</p><p>刪除重複文件，就運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -deleteduplicates true ~/Downloads</span></span></code></pre></div><p>如果你不想忽略空文件，並且和所喲重複文件一起刪除。運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -deleteduplicates true -ignoreempty false ~/Downloads</span></span></code></pre></div><p>更多細節，參照幫助部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind --help</span></span></code></pre></div><p>手冊頁：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man rdfind</span></span></code></pre></div><h4 id="_2-fdupes" tabindex="-1">2. Fdupes <a class="header-anchor" href="#_2-fdupes" aria-label="Permalink to “2. Fdupes”">​</a></h4><p><strong>Fdupes</strong> 是另一個在指定目錄以及子目錄中識別和移除重複文件的命令列工具。這是一個使用 C 語言編寫的自由開源工具。Fdupes 通過對比文件大小、部分 MD5 簽名、全部 MD5 簽名，最後執行逐個字節對比校驗來識別重複文件。</p><p>與 Rdfind 工具類似，Fdupes 附帶非常少的選項來執行操作，如：</p><ul><li>在目錄和子目錄中遞歸的搜索重複文件</li><li>從計算中排除空文件和隱藏文件</li><li>顯示重複文件大小</li><li>出現重複文件時立即刪除</li><li>使用不同的擁有者/組或權限位來排除重複文件</li><li>更多</li></ul><p><strong>安裝 Fdupes</strong></p><p>Fdupes 存在於大多數 Linux 發行版的默認倉庫中。</p><p>在 Arch Linux 和它的變種如 Antergos、Manjaro Linux 上，如下使用 Pacman 安裝它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S fdupes</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install fdupes</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install fdupes</span></span></code></pre></div><p>在 RHEL、CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install fdupes</span></span></code></pre></div><p><strong>用法</strong></p><p>Fdupes 用法非常簡單。僅運行下面的命令就可以在目錄中找到重複文件，如：<code>~/Downloads</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes ~/Downloads</span></span></code></pre></div><p>我係統中的樣例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home/sk/Downloads/Hyperledger.pdf</span></span>
<span class="line"><span>/home/sk/Downloads/Hyperledger(1).pdf</span></span></code></pre></div><p>你可以看到，在 <code>/home/sk/Downloads/</code> 目錄下有一個重複文件。它僅顯示了父級目錄中的重複文件。如何顯示子目錄中的重複文件？像下面一樣，使用 <code>-r</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -r ~/Downloads</span></span></code></pre></div><p>現在你將看到 <code>/home/sk/Downloads/</code> 目錄以及子目錄中的重複文件。</p><p>Fdupes 也可用來從多個目錄中迅速查找重複文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes ~/Downloads ~/Documents/ostechnix</span></span></code></pre></div><p>你甚至可以搜索多個目錄，遞歸搜索其中一個目錄，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes ~/Downloads -r ~/Documents/ostechnix</span></span></code></pre></div><p>上面的命令將搜索 <code>~/Downloads</code> 目錄，<code>~/Documents/ostechnix</code> 目錄和它的子目錄中的重複文件。</p><p>有時，你可能想要知道一個目錄中重複文件的大小。你可以使用 <code>-S</code> 選項，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -S ~/Downloads</span></span>
<span class="line"><span>403635 bytes each:</span></span>
<span class="line"><span>/home/sk/Downloads/Hyperledger.pdf</span></span>
<span class="line"><span>/home/sk/Downloads/Hyperledger(1).pdf</span></span></code></pre></div><p>類似的，為了顯示父目錄和子目錄中重複文件的大小，使用 <code>-Sr</code> 選項。</p><p>我們可以在計算時分別使用 <code>-n</code> 和 <code>-A</code> 選項排除空白文件以及排除隱藏文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -n ~/Downloads</span></span>
<span class="line"><span>$ fdupes -A ~/Downloads</span></span></code></pre></div><p>在搜索指定目錄的重複文件時，第一個命令將排除零長度文件，後面的命令將排除隱藏文件。</p><p>彙總重複文件信息，使用 <code>-m</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -m ~/Downloads</span></span>
<span class="line"><span>1 duplicate files (in 1 sets), occupying 403.6 kilobytes</span></span></code></pre></div><p>刪除所有重複文件，使用 <code>-d</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -d ~/Downloads</span></span></code></pre></div><p>樣例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1] /home/sk/Downloads/Hyperledger Fabric Installation.pdf</span></span>
<span class="line"><span>[2] /home/sk/Downloads/Hyperledger Fabric Installation(1).pdf</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Set 1 of 1, preserve files [1 - 2, all]:</span></span></code></pre></div><p>這個命令將提示你保留還是刪除所有其他重複文件。輸入任一號碼保留相應的文件，並刪除剩下的文件。當使用這個選項的時候需要更加註意。如果不小心，你可能會刪除原文件。</p><p>如果你想要每次保留每個重複文件集合的第一個文件，且無提示的刪除其他文件，使用 <code>-dN</code> 選項（不推薦）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -dN ~/Downloads</span></span></code></pre></div><p>當遇到重複文件時刪除它們，使用 <code>-I</code> 標誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -I ~/Downloads</span></span></code></pre></div><p>關於 Fdupes 的更多細節，查看幫助部分和 man 頁面。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes --help</span></span>
<span class="line"><span>$ man fdupes</span></span></code></pre></div><h4 id="_3-fslint" tabindex="-1">3. FSlint <a class="header-anchor" href="#_3-fslint" aria-label="Permalink to “3. FSlint”">​</a></h4><p><strong>FSlint</strong> 是另外一個查找重複文件的工具，有時我用它去掉 Linux 系統中不需要的重複文件並釋放磁盤空間。不像另外兩個工具，FSlint 有 GUI 和 CLI 兩種模式。因此對於新手來説它更友好。FSlint 不僅僅找出重複文件，也找出壞符號鏈接、壞名字文件、臨時文件、壞的用户 ID、空目錄和非精簡的二進制文件等等。</p><p><strong>安裝 FSlint</strong></p>`,81)),e("p",null,[s[21]||(s[21]=i("FSlint 存在於 ",-1)),n(a,{href:"https://aur.archlinux.org/packages/fslint/"},{default:l(()=>[...s[20]||(s[20]=[i("AUR",-1)])]),_:1}),s[22]||(s[22]=i("，因此你可以使用任一 AUR 助手安裝它。",-1))]),s[49]||(s[49]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yay -S fslint</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install fslint</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install fslint</span></span></code></pre></div><p>在 RHEL，CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install fslint</span></span></code></pre></div><p>一旦安裝完成，從菜單或者應用程序啓動器啓動它。</p><p>FSlint GUI 展示如下：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/09/fslint-1.png" alt=""></p><p>如你所見，FSlint 界面友好、一目瞭然。在 “Search path” 欄，添加你要掃描的目錄路徑，點擊左下角 “Find” 按鈕查找重複文件。驗證遞歸選項可以在目錄和子目錄中遞歸的搜索重複文件。FSlint 將快速的掃描給定的目錄並列出重複文件。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/fslint-2.png" alt=""></p><p>從列表中選擇那些要清理的重複文件，也可以選擇 “Save”、“Delete”、“Merge” 和 “Symlink” 操作他們。</p><p>在 “Advanced search parameters” 欄，你可以在搜索重複文件的時候指定排除的路徑。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/09/fslint-3.png" alt=""></p><p><strong>FSlint 命令列選項</strong></p><p>FSlint 提供下面的 CLI 工具集在你的文件系統中查找重複文件。</p><ul><li><code>findup</code> — 查找重複文件</li><li><code>findnl</code> — 查找名稱規範（有問題的文件名）</li><li><code>findu8</code> — 查找非法的 utf8 編碼的文件名</li><li><code>findbl</code> — 查找壞鏈接（有問題的符號鏈接）</li><li><code>findsn</code> — 查找同名文件（可能有衝突的文件名）</li><li><code>finded</code> — 查找空目錄</li><li><code>findid</code> — 查找死用户的文件</li><li><code>findns</code> — 查找非精簡的可執行文件</li><li><code>findrs</code> — 查找文件名中多餘的空白</li><li><code>findtf</code> — 查找臨時文件</li><li><code>findul</code> — 查找可能未使用的庫</li><li><code>zipdir</code> — 回收 ext2 目錄項下浪費的空間</li></ul><p>所有這些工具位於 <code>/usr/share/fslint/fslint/fslint</code> 下面。</p><p>例如，在給定的目錄中查找重複文件，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /usr/share/fslint/fslint/findup ~/Downloads/</span></span></code></pre></div><p>類似的，找出空目錄命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /usr/share/fslint/fslint/finded ~/Downloads/</span></span></code></pre></div><p>獲取每個工具更多細節，例如：<code>findup</code>，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /usr/share/fslint/fslint/findup --help</span></span></code></pre></div><p>關於 FSlint 的更多細節，參照幫助部分和 man 頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /usr/share/fslint/fslint/fslint --help</span></span>
<span class="line"><span>$ man fslint</span></span></code></pre></div><h5 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h5><p>現在你知道在 Linux 中，使用三個工具來查找和刪除不需要的重複文件。這三個工具中，我經常使用 Rdfind。這並不意味着其他的兩個工具效率低下，因為到目前為止我更喜歡 Rdfind。好了，到你了。你的最喜歡哪一個工具呢？為什麼？在下面的評論區留言讓我們知道吧。</p><p>就到這裏吧。希望這篇文章對你有幫助。更多的好東西就要來了，敬請期待。</p><p>謝謝！</p><hr>`,32)),e("p",null,[s[24]||(s[24]=i("via: ",-1)),n(a,{href:"https://www.ostechnix.com/how-to-find-and-delete-duplicate-files-in-linux/"},{default:l(()=>[...s[23]||(s[23]=[i("https://www.ostechnix.com/how-to-find-and-delete-duplicate-files-in-linux/",-1)])]),_:1})]),e("p",null,[s[29]||(s[29]=i("作者：",-1)),n(a,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...s[25]||(s[25]=[i("SK",-1)])]),_:1}),s[30]||(s[30]=i(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[26]||(s[26]=[i("lujun9972",-1)])]),_:1}),s[31]||(s[31]=i(" 譯者：",-1)),n(a,{href:"https://github.com/pygmalion666"},{default:l(()=>[...s[27]||(s[27]=[i("pygmalion666",-1)])]),_:1}),s[32]||(s[32]=i(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[28]||(s[28]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[35]||(s[35]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[33]||(s[33]=[i("LCTT",-1)])]),_:1}),s[36]||(s[36]=i(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:l(()=>[...s[34]||(s[34]=[i("Linux中國",-1)])]),_:1}),s[37]||(s[37]=i(" 榮譽推出",-1))])])}const C=p(h,[["render",g]]);export{x as __pageData,C as default};
